    gilded_sandmullerblade = { name = "Pozlačen lopice mešalca peska", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen lopice mešalca peska za livarje." },
